if __name__ == "__main__":
    revise_domain("339", "339_generative_art", GENERATIVE_ART,
                  "Generative art as human and computational visual practice with documented expressive choices, collaborators, sources, display, and preservation.",
                  "dated artworks and artist records, versioned tools, production files, exhibition materials, U.S. Copyright Office guidance, and audience research",
                  "Name creator, workflow, model version, source provenance, jurisdiction, and display context. Do not infer ownership or authorship from appearance alone.")
    revise_domain("340", "340_ai_music", AI_MUSIC,
                  "AI music as generated or assisted composition and audio production with musicians, recordings, models, rights, and listeners.",
                  "session files, stems, credits, consent and licensing records, versioned tool documentation, and attributed listener research",
                  "Name track, contributors, source recordings, tool version, and jurisdiction. Retain legacy visual-art slugs for routing while their questions address sound.")
    revise_domain("341", "341_ai_voice", AI_VOICE,
                  "AI voice as synthetic speech and digital vocal performance with consent, provenance, disclosure, accessibility, and performer control.",
                  "consented performer accounts, recording and production records, rights agreements, versioned system documentation, and listener tests",
                  "Name voice owner, approved use, model version, audience, and jurisdiction. Avoid generating impersonation instructions and retain legacy art slugs for routing.")
    rows = audit()
    print(f"Plans: {len(rows)}; reviewed question designs: {sum(r['status'] == 'editorial_question_reviewed' for r in rows)}")
